import type { ShopperSearchTypes } from 'commerce-sdk-isomorphic';
import { getPriceData, filterImageGroups } from '@salesforce/retail-react-app/app/utils/product-utils';
import { productUrlBuilder } from '@salesforce/retail-react-app/app/utils/url';
import type {
  ZimmProductCardBaseProps,
  ZimmProductCardPlpVariation,
  ZimmProductCardImage,
} from '../../components/ui-kits/organisms/zimmProductCard';
import type { ZimmSizeChipValue } from '../../components/ui-kits/molecules/zimmSizeChipGroup';

// This mapper is PLP-only by design, so it returns the narrowed shape directly rather than the
// full `ZimmProductCardProps` union — letting a caller pass the result straight to a
// PLP-typed component (like this page's own `ProductListCard`) with no re-narrowing needed.
type ProductListCardResult = ZimmProductCardBaseProps & ZimmProductCardPlpVariation;

/**
 * `c_productBadges` is a custom SFCC attribute (SFCC-225's own already-merged SCAPI hook) with no
 * typed field on the base SDK's `ProductSearchHit` — it only reaches this shape via that type's
 * own `{[key: string]: any}` index signature. Narrowed here to the one shape this mapper reads,
 * rather than trusting `any` at every call site.
 */
export type ProductListSearchHit = ShopperSearchTypes.ProductSearchHit & {
  c_productBadges?: Array<{ productBadge?: string }>;
};

type RawImage = { alt?: string; disBaseLink?: string; link?: string };

const toCardImage = (image: RawImage | undefined): ZimmProductCardImage | undefined => {
  const src = image?.disBaseLink ?? image?.link;
  if (!src) return undefined;
  return { src, alt: image?.alt ?? '' };
};

/** The correctly-sized product image view the colour+viewType-scoped trio below all read — never
 *  serve an arbitrary-sized image at gallery/thumbnail size (AGENTS.md's image-sizing guidance).
 *  Matches `recentlyViewedCard.ts`'s / `recentlyViewedFullHistoryCard.ts`'s own identically-named,
 *  identically-valued constant. Named per conventions.md's no-magic-strings rule. */
const MEDIUM_VIEW_TYPE = 'medium';

/**
 * The real, live SFCC `variationAttributes`/`variationValues` id for colour — confirmed directly
 * against a real 2-colour product (`ZWNEWPRD04`, colours BLK/TAN), each with its own separate
 * `imageGroups` entry tagged `variationAttributes: [{id: 'color', values: [{value: 'BLK'}]}]`.
 * Named per conventions.md's no-magic-strings rule. American spelling because this documents the
 * real, live SFCC attribute id (data, not a Zimmermann-authored identifier) — see
 * `resolveRepresentativeColour` below for the Australian-spelled function/variable naming this
 * constant feeds.
 */
const COLOR_VARIATION_ATTRIBUTE_ID = 'color';

/**
 * Resolves the colour SFCC's own search index already chose to represent this hit — added
 * 2026-09-09 (plan addendum §7, step C1) to close a confirmed live defect: this mapper's gallery
 * used to be picked with no colour (or viewType) filter at all — "whichever image group has the
 * most images" — so a multi-colour product's gallery could show the wrong colour's photos.
 * Confirmed live against a real 2-colour product (`ZWNEWPRD04`, BLK/TAN): each colour has its own
 * separate, explicitly-tagged `imageGroups` entry, so the old "most images wins" heuristic could
 * (and did) pick the wrong one whenever the off-colour group happened to have more photos.
 *
 * `hit.representedProduct.id` is the specific variant SFCC's search index already picked to
 * represent this (typically master-level) hit; matching it against `hit.variants[]` by
 * `productId` finds that exact variant's own `variationValues.color` — deterministic and
 * server-decided, no guessing and no reliance on the untyped `c_color` custom attribute. There is
 * no colour selector on this card and none is being added here — this only teaches the mapper to
 * respect the colour SFCC already chose, not to let the shopper pick a different one.
 *
 * @returns `undefined` when there is no `representedProduct`, no `variants` array, or no variant
 *   whose `productId` matches it — callers scope to `viewType` alone in that case (see
 *   `selectColourScopedImages` below), never back to the old fully-unscoped "biggest group
 *   anywhere" pick.
 */
export const resolveRepresentativeColour = (hit: ProductListSearchHit): string | undefined => {
  const representedProductId = hit.representedProduct?.id;
  if (!representedProductId) return undefined;

  const representativeVariant = hit.variants?.find((variant) => variant.productId === representedProductId);
  return representativeVariant?.variationValues?.[COLOR_VARIATION_ATTRIBUTE_ID];
};

/**
 * The colour+viewType-scoped image array `selectGalleryImages`, `hoverImage`, and
 * `primaryImageFallbacks` are all derived from — resolved via `resolveRepresentativeColour` so
 * all three read the same deterministic colour. Replaces the old viewType/colour-agnostic
 * "whichever group has the most images" pick entirely (plan addendum §7, step C1, 2026-09-09) —
 * when no colour resolves (single-colour product, or no `variants`/`representedProduct` match),
 * this still scopes to `viewType: 'medium'` alone and never falls back to that old fully-unscoped
 * behaviour.
 *
 * Only the first matching image group is read (`filteredGroups[0]`), matching
 * `recentlyViewedCard.ts`'s / `recentlyViewedFullHistoryCard.ts`'s own `selectPrimaryImage`
 * precedent for the same `filterImageGroups` call — a colour+viewType pair identifies at most one
 * real group in practice, so there is nothing to gain from reading past the first match.
 *
 * `hit.image` (the required `primaryImage` slot) is untouched by this and resolved exactly as
 * before by `selectProductListCard` — this array only ever supplies the gallery/hover-swap/
 * fallback candidates, never the primary image itself.
 */
const selectColourScopedImages = (hit: ProductListSearchHit): ZimmProductCardImage[] => {
  const colour = resolveRepresentativeColour(hit);
  const filteredGroups = filterImageGroups(hit.imageGroups ?? [], {
    viewType: MEDIUM_VIEW_TYPE,
    variationValues: colour ? { [COLOR_VARIATION_ATTRIBUTE_ID]: colour } : {},
  }) as ShopperSearchTypes.ImageGroup[];

  const groupImages = filteredGroups[0]?.images ?? [];
  return groupImages.map(toCardImage).filter((img): img is ZimmProductCardImage => Boolean(img));
};

/**
 * Picks this hit's gallery from the colour+viewType-scoped image array (see
 * `selectColourScopedImages` above) — rebuilt 2026-09-09 (plan addendum §7, step C1) to replace
 * the old viewType/colour-agnostic "biggest group anywhere" pick, a confirmed live defect (see
 * `selectColourScopedImages`'s own docblock). Returns `undefined` for 0 or 1 resulting images,
 * matching `ZimmProductCardMedia`'s own "no gallery" contract for that case — this function
 * doesn't duplicate that check, it just never returns a 1-length array.
 */
export const selectGalleryImages = (hit: ProductListSearchHit): ZimmProductCardImage[] | undefined => {
  const images = selectColourScopedImages(hit);
  return images.length > 1 ? images : undefined;
};

/**
 * Reads the "size" variation attribute (if this hit has one) into the shape
 * `ZimmSizeChipGroup` expects. `orderable` on each value already reflects real stock per that
 * specific size, so it maps directly to `isDisabled` with no extra lookup needed.
 */
export const selectSizeChipValues = (hit: ProductListSearchHit): ZimmSizeChipValue[] => {
  const sizeAttribute = hit.variationAttributes?.find((attr) => attr.id === 'size');
  return (sizeAttribute?.values ?? []).map((value) => ({
    value: value.value,
    label: value.name ?? value.value,
    isDisabled: value.orderable === false,
  }));
};

/** What `resolveOrderableVariant` resolves a selected size chip value to — the real, orderable
 *  SKU for that specific size, not the master/represented-product id this hit otherwise defaults
 *  to. `price` is the variant's own (`ShopperSearchTypes.Variant`'s own field, confirmed real via
 *  a live product-detail check, 2026-09-08), which can genuinely differ from the hit's own flat
 *  `price` across sizes (e.g. plus sizes priced higher) — callers should prefer this over the
 *  hit's own price once a variant has been resolved. */
export type ResolvedVariant = {
  productId: string;
  price: number | undefined;
  orderable: boolean;
};

/**
 * Resolves a selected size CHIP VALUE to its real orderable variant — added 2026-09-08 (Gap 3:
 * "size-aware Add to Bag" was previously cosmetic; selecting a chip never changed what got added
 * to the bag at all). Confirmed live against product `4673TS251`: `hit.variants` is real and
 * populated (`expand: [...,'variations']`, already requested by this page's own search call),
 * each entry carrying its own real `productId` (e.g. `4673TS251GVSCP0P`) keyed by
 * `variationValues.size` (e.g. `'0P'`) — exactly the lookup this function performs.
 *
 * Returns `null` when there is no matching variant at all (no `variants` array, or no entry
 * whose `variationValues.size` equals `sizeValue`) — callers are expected to fall back to this
 * hit's own default `representedProduct`/`productId` resolution in that case, the same default
 * that already existed before size-aware add-to-bag was ever selectable.
 */
export const resolveOrderableVariant = (hit: ProductListSearchHit, sizeValue: string): ResolvedVariant | null => {
  const variant = hit.variants?.find((candidate) => candidate.variationValues?.size === sizeValue);
  if (!variant) return null;

  return {
    productId: variant.productId,
    price: variant.price,
    orderable: variant.orderable !== false,
  };
};

/**
 * `getPriceData`'s own return shape (base SFCC, `product-utils.js:123-170`), narrowed to the
 * three fields this mapper reads — ported verbatim from `recentlyViewedFullHistoryCard.ts`'s own
 * identically-named type, same reasoning: `@salesforce/retail-react-app` ships no types for this
 * subpath (falls through `overrides/app/types/vendor.d.ts`'s catch-all ambient `any`), so this
 * documents an assumed shape rather than letting `any` propagate — the real correctness proof is
 * this file's own test comparing against a real `getPriceData` call, not this annotation alone.
 */
type SfccPriceData = {
  /** `findLowestPrice()`'s own `minPrice` — replaces the flat `hit.price` field this mapper used
   *  to read for `currentPrice` (2026-09-08: now sourced from the same call as `originalPrice`,
   *  closing the "two fields could disagree on a multi-variant hit" gap the old code risked). */
  currentPrice: number;
  /** The highest tiered price found — "was" price. `undefined` when the hit has no
   *  `tieredPrices` at all (there is then no maximum to compute). */
  listPrice: number | undefined;
  /** `currentPrice < listPrice` — always `false`, never `true`, when `listPrice` is `undefined`. */
  isOnSale: boolean;
};

/**
 * Derives `currentPrice`/`originalPrice` from a single `getPriceData(hit)` call — ported verbatim
 * from `recentlyViewedFullHistoryCard.ts`'s own `selectPriceFields` (see that file's own docblock
 * for why both fields must come from the one call rather than mixing a flat price field for one
 * and `getPriceData` for the other). No `opts` passed — the default `quantity: 1` is correct for
 * a single-unit card display. No hardcoded fallback currency — if either the price or the
 * currency is absent, formatting is skipped rather than guessed.
 *
 * **Closes 2026-09-08's confirmed gap**: this hit's own `perPricebook: true` + `expand: [...,
 * 'prices']` request (product-list/index.tsx) does carry real tiered pricing — checked directly
 * against a live on-sale product via the Shopper Products detail endpoint (same underlying
 * pricebook data; the search endpoint's own live response couldn't be intercepted directly, since
 * this page's initial data arrives via SSR with no separate client-side request to inspect) —
 * closing the honest "not checked against a live hit" caveat this file's own history carried.
 */
const selectPriceFields = (
  hit: ProductListSearchHit,
  formatPrice: (amount: number, currency: string) => string,
): Pick<ProductListCardResult, 'currentPrice' | 'originalPrice'> => {
  const priceData: SfccPriceData = getPriceData(hit);

  const currentPrice =
    typeof priceData.currentPrice === 'number' && hit.currency
      ? formatPrice(priceData.currentPrice, hit.currency)
      : undefined;

  // Only set when isOnSale is true -- a not-on-sale hit must not render a crossed-out price
  // identical to its current one.
  const originalPrice =
    priceData.isOnSale && typeof priceData.listPrice === 'number' && hit.currency
      ? formatPrice(priceData.listPrice, hit.currency)
      : undefined;

  return { currentPrice, originalPrice };
};

/**
 * Maps one real product-search hit to `ZimmProductCardProps` (`variation: 'plp'`) for this quick
 * test integration. `formatPrice` is passed in rather than built here — the page already owns an
 * `intl`-based formatter, and this stays a pure function with no `react-intl` dependency of its
 * own, the same split the page's existing wishlist-toast handlers already follow.
 *
 * Returns `null` when there's no usable name or primary image — mirrors `ZimmProductName`'s own
 * "no render without a name" contract, and `ZimmProductCardBaseProps.primaryImage`'s required-ness
 * (a card with neither has nothing to legitimately render).
 *
 * **`hoverImage`/`primaryImageFallbacks` added 2026-09-09 (plan addendum §7, step C1)** — both
 * read off the same colour+viewType-scoped array `images` is built from (see
 * `selectColourScopedImages`), never off `hit.image`. `hit.image` (`primaryImage` above) is
 * untouched by this addendum and still resolved exactly as before.
 */
export const selectProductListCard = (
  hit: ProductListSearchHit,
  formatPrice: (amount: number, currency: string) => string,
): ProductListCardResult | null => {
  const primaryImage = toCardImage(hit.image);
  if (!hit.productName || !primaryImage) return null;

  const { currentPrice, originalPrice } = selectPriceFields(hit, formatPrice);

  // hoverImage/primaryImageFallbacks are the second entry and the remainder of the same
  // colour+viewType-scoped array `images` (below) is built from — see
  // `selectColourScopedImages`'s own docblock. Computed via a second, independent call so
  // `selectGalleryImages` keeps its own single-argument, independently-testable public signature
  // rather than needing the array threaded in. `hit.image` (primaryImage above) is untouched by
  // this — it stays the sole source for primaryImage, exactly as before.
  const colourScopedImages = selectColourScopedImages(hit);
  const hoverImage = colourScopedImages[1];
  const primaryImageFallbacks = colourScopedImages.slice(2);

  return {
    id: hit.productId,
    href: productUrlBuilder({ id: hit.productId }),
    name: hit.productName,
    headingLevel: 'h3',
    primaryImage,
    primaryImageFallbacks,
    hoverImage,
    images: selectGalleryImages(hit),
    currentPrice,
    originalPrice,
    isUnavailable: hit.orderable === false,
    // Single highest-priority badge — SFCC-225's own confirmed shape (see the organism's own
    // docblock, "Badge count" note): only one badge is ever shown, never a list.
    badge: hit.c_productBadges?.[0]?.productBadge,
    variation: 'plp',
    sizeChipValues: selectSizeChipValues(hit),
  };
};

