import type { ShopperSearchTypes } from 'commerce-sdk-isomorphic';
import { getPriceData, filterImageGroups } from '@salesforce/retail-react-app/app/utils/product-utils';
import { productUrlBuilder } from '@salesforce/retail-react-app/app/utils/url';
import type {
  ZimmProductCardBaseProps,
  ZimmProductCardPlpVariation,
  ZimmProductCardImage,
} from '../../components/ui-kits/organisms/zimmProductCard';
import type { ZimmSizeChipValue } from '../../components/ui-kits/molecules/zimmSizeChipGroup';

// This mapper is PLP-only by design, so it returns the narrowed shape directly rather than the
// full `ZimmProductCardProps` union — letting a caller pass the result straight to a
// PLP-typed component (like this page's own `ProductListCard`) with no re-narrowing needed.
type ProductListCardResult = ZimmProductCardBaseProps & ZimmProductCardPlpVariation;

/**
 * `c_productBadges` is a custom SFCC attribute (SFCC-225's own already-merged SCAPI hook) with no
 * typed field on the base SDK's `ProductSearchHit` — it only reaches this shape via that type's
 * own `{[key: string]: any}` index signature. Narrowed here to the one shape this mapper reads,
 * rather than trusting `any` at every call site.
 */
export type ProductListSearchHit = ShopperSearchTypes.ProductSearchHit & {
  c_productBadges?: Array<{ productBadge?: string }>;
};

// The image viewType this mapper's gallery/hover-swap/fallback logic reads — matches
// recentlyViewedCard.ts's and recentlyViewedFullHistoryCard.ts's own identically-named constant:
// a real, correctly-sized product image (AGENTS.md's image-sizing guidance), not the arbitrary
// "whichever viewType has the most images" this file used to pick, and not necessarily the same
// viewType as hit.image's own separately-configured pick (see resolveRepresentativeColour's own
// docblock).
const MEDIUM_VIEW_TYPE = 'medium';

// Named per conventions.md's no-magic-strings rule, for this fix's own new colour-resolution logic
// only — the pre-existing 'size' literal in selectSizeChipValues below is untouched (Minimal
// Changes), not part of this fix's scope.
const COLOUR_VARIATION_ATTRIBUTE_ID = 'color';

type RawImage = { alt?: string; disBaseLink?: string; link?: string };

const toCardImage = (image: RawImage | undefined): ZimmProductCardImage | undefined => {
  const src = image?.disBaseLink ?? image?.link;
  if (!src) return undefined;
  return { src, alt: image?.alt ?? '' };
};

/**
 * Resolves the colour SFCC itself already picked to represent this hit — confirmed live
 * 2026-09-09 that this is a real, server-side decision: a master/style-level search hit shows one
 * colour at a time, with no colour selector on this card to let a shopper pick a different one.
 * `hit.representedProduct.id` is SFCC's own already-resolved variant reference; matching it
 * against `hit.variants` (already requested via this page's own `expand: [..., 'variations']`)
 * reads that exact variant's real `variationValues.color` — no guessing, and no reliance on the
 * untyped `c_color` custom attribute (same "don't trust an unconfirmed custom field" reasoning
 * `badge` below already applies to `c_productBadges`).
 *
 * Returns `undefined` for a genuinely single-colour product (no `representedProduct`/`variants`
 * data, or no variant carrying a colour value at all) — callers degrade to a viewType-only image
 * lookup in that case, never a guess at which colour to prefer.
 */
export const resolveRepresentativeColour = (hit: ProductListSearchHit): string | undefined => {
  const representedId = hit.representedProduct?.id;
  if (!representedId) return undefined;

  const variant = hit.variants?.find((candidate) => candidate.productId === representedId);
  return variant?.variationValues?.[COLOUR_VARIATION_ATTRIBUTE_ID];
};

/**
 * The one real image group this hit's gallery, hover-swap image, and primary-image fallback
 * candidates all read from — 2026-09-09 fix, replacing "whichever image group across every
 * viewType and every colour happens to have the most images" (this function's previous
 * approach), which could silently mix in a different colour's photos, or a `large`/`small`
 * viewType instead of `medium`, for any multi-colour product. Confirmed live against a real
 * two-colour product: SFCC tags each `imageGroups` entry with its own `variationAttributes`
 * (colour), so an unscoped pick really can land on the wrong one. Scoped to `MEDIUM_VIEW_TYPE`
 * unconditionally, and additionally to `resolveRepresentativeColour`'s own result when one
 * resolves — the same `filterImageGroups` call already proven on
 * `feature/zimmproductcard-live-demo`'s own mapper.
 *
 * Deliberately does NOT touch `hit.image` (this hit's own separately-configured "official"
 * search-result image — confirmed live 2026-09-09 to be `ProductSearchHit.image`'s own documented
 * "first image ... for the configured viewtype", which is not necessarily `MEDIUM_VIEW_TYPE` and
 * can differ per product depending on which viewtypes exist for it). That stays this mapper's
 * primary image, unchanged — this array only ever supplies the gallery, the hover-swap image, and
 * fallback candidates alongside it.
 */
const selectScopedImages = (hit: ProductListSearchHit): ZimmProductCardImage[] => {
  const colour = resolveRepresentativeColour(hit);
  const groups = filterImageGroups(hit.imageGroups ?? [], {
    viewType: MEDIUM_VIEW_TYPE,
    variationValues: colour ? { [COLOUR_VARIATION_ATTRIBUTE_ID]: colour } : {},
  }) as ShopperSearchTypes.ImageGroup[];
  const images = groups[0]?.images ?? [];

  return images.map(toCardImage).filter((img): img is ZimmProductCardImage => Boolean(img));
};

/**
 * This hit's gallery, from `selectScopedImages` above. Returns `undefined` for 0 or 1 resulting
 * images, matching `ZimmProductCardMedia`'s own "no gallery" contract for that case.
 */
export const selectGalleryImages = (hit: ProductListSearchHit): ZimmProductCardImage[] | undefined => {
  const images = selectScopedImages(hit);
  return images.length > 1 ? images : undefined;
};

