  const sizeAttribute = hit.variationAttributes?.find((attr) => attr.id === 'size');
  return (sizeAttribute?.values ?? []).map((value) => ({
    value: value.value,
    label: value.name ?? value.value,
    isDisabled: value.orderable === false,
  }));
};

/** What `resolveOrderableVariant` resolves a selected size chip value to — the real, orderable
 *  SKU for that specific size, not the master/represented-product id this hit otherwise defaults
 *  to. `price` is the variant's own (`ShopperSearchTypes.Variant`'s own field, confirmed real via
 *  a live product-detail check, 2026-09-08), which can genuinely differ from the hit's own flat
 *  `price` across sizes (e.g. plus sizes priced higher) — callers should prefer this over the
 *  hit's own price once a variant has been resolved. */
